import { writeRecord } from './db.js'

export async function saveUser(user) {
  const record = { id: user.id, name: user.name }
  writeRecord(record)
  return { saved: true }
}

export async function writeRecord(record) {
  await fetch('https://db.example.test/records', {
    method: 'POST',
    body: JSON.stringify(record),
  })
}
